//[example_http_client_methods

#include <boost/asio/connect.hpp>
#include <boost/asio/ip/tcp.hpp>
#include <cstdlib>
#include <iostream>
#include <string>
#include <webcpp/beast/core.hpp>

namespace beast = webcpp::beast;  // from <webcpp/beast.hpp>
namespace http = beast::http;     // from <webcpp/beast/http.hpp>
// from <boost/asio.hpp>
using webcpp::asio::ip::tcp;  // from <boost/asio/ip/tcp.hpp>

// perform a get request
namespace {
void do_get(beast::browser::http_byte_stream<beast::tcp_stream>& stream,
            http::request<http::string_body>& req, beast::flat_buffer buffer,
            http::response<http::dynamic_body>& res) {
    req.target("/get");
    req.method(beast::http::verb::get);
    http::write(stream, req);
    http::read(stream, buffer, res);
}

// perform a head request
void do_head(beast::browser::http_byte_stream<beast::tcp_stream>& stream,
             http::request<http::string_body>& req, beast::flat_buffer buffer,
             http::response<http::dynamic_body>& res) {
    // we reuse the get endpoint
    req.target("/get");
    req.method(beast::http::verb::head);
    http::write(stream, req);

    /* the head response will send back a content-length
     * without a body. The other requests don't set content-length when not
     * sending a body back.
     *
     * the response parser doesn't know that we sent head,
     * so we need to manually make sure we're only reading the header
     * otherwise we're waiting forever for data.
     */

    http::response_parser<http::dynamic_body> p;
    http::read_header(stream, buffer, p);
    // move the result over
    res = p.release();
}

// perform a patch request
void do_patch(beast::browser::http_byte_stream<beast::tcp_stream>& stream,
              http::request<http::string_body>& req, beast::flat_buffer buffer,
              http::response<http::dynamic_body>& res) {
    req.target("/patch");
    req.method(beast::http::verb::patch);
    req.body() = "Some random patch data";
    req.prepare_payload();  // set content-length based on the body
    http::write(stream, req);
    http::read(stream, buffer, res);
}

// perform a put request
void do_put(beast::browser::http_byte_stream<beast::tcp_stream>& stream,
            http::request<http::string_body>& req, beast::flat_buffer buffer,
            http::response<http::dynamic_body>& res) {
    req.target("/put");
    req.method(beast::http::verb::put);
    req.body() = "Some random put data";
    req.prepare_payload();  // set content-length based on the body
    http::write(stream, req);
    http::read(stream, buffer, res);
}

// perform a post request
void do_post(beast::browser::http_byte_stream<beast::tcp_stream>& stream,
             http::request<http::string_body>& req, beast::flat_buffer buffer,
             http::response<http::dynamic_body>& res) {
    req.target("/post");
    req.method(beast::http::verb::post);
    req.body() = "Some random post data";
    req.prepare_payload();  // set content-length based on the body
    http::write(stream, req);
    http::read(stream, buffer, res);
}

// perform a delete request
void do_delete(beast::browser::http_byte_stream<beast::tcp_stream>& stream,
               http::request<http::string_body>& req, beast::flat_buffer buffer,
               http::response<http::dynamic_body>& res) {
    req.target("/delete");
    req.method(beast::http::verb::delete_);
    // NOTE: delete doesn't require a body
    req.body() = "Some random delete data";
    req.prepare_payload();  // set content-length based on the body
    http::write(stream, req);
    http::read(stream, buffer, res);
}

// Performs an HTTP request against httpbin.cpp.al and prints request & response
// The process entry point retains the standard char** argv signature.
// NOLINTNEXTLINE(misc-const-correctness)
int application_main(int argc, char** argv) {
    {
        // Check command line arguments.
        if (argc != 2) {
            std::cerr << "Usage: http-client-method <method> \n"
                      << "Example:\n"
                      << "    http-client-method get\n"
                      << "    http-client-method post\n";
            return EXIT_FAILURE;
        }

        for (char* c = argv[1]; *c != '\0'; c++) {
            *c = static_cast<char>(std::tolower(*c));
        }
        beast::string_view method{argv[1]};

        // The io_context is required for all I/O
        webcpp::asio::io_context ioc;

        // These objects perform our I/O
        webcpp::asio::ip::tcp::resolver resolver(ioc);
        beast::tcp_stream transport(ioc);
        beast::browser::http_byte_stream stream(transport);

        // Look up the domain name
        auto const results =
            webcpp_fixture::resolve(resolver, webcpp_fixture::host(), webcpp_fixture::port());

        // Make the connection on the IP address we get from a lookup
        transport.connect(results);

        // Set up an HTTP GET request message
        http::request<http::string_body> req;
        req.set(http::field::host, webcpp_fixture::host());

        // This buffer is used for reading and must be persisted
        beast::flat_buffer buffer;

        // Declare a container to hold the response
        http::response<http::dynamic_body> res;

        if (method == "get") {
            do_get(stream, req, buffer, res);
        } else if (method == "head") {
            do_head(stream, req, buffer, res);
        } else if (method == "patch") {
            do_patch(stream, req, buffer, res);
        } else if (method == "put") {
            do_put(stream, req, buffer, res);
        } else if (method == "post") {
            do_post(stream, req, buffer, res);
        } else if (method == "delete") {
            do_delete(stream, req, buffer, res);
        } else {
            std::cerr << "Unknown method: " << method << '\n';
            return EXIT_FAILURE;
        }

        // Write the message to standard out
        std::cout << "Request send:\n-----------------------------\n" << req << '\n';

        // Write the message to standard out
        std::cout << "\n\nResponse received:\n-----------------------------\n" << res << '\n';

        // Gracefully close the socket
        beast::error_code ec;
        transport.socket().shutdown(tcp::socket::shutdown_both, ec);

        // not_connected happens sometimes
        // so don't bother reporting it.
        //
        if (ec && ec != beast::errc::not_connected) {
            webcpp_fixture::fail_stop();
        }

        // If we get here then the connection is closed gracefully
    }
    return EXIT_SUCCESS;
}

//]

}  // namespace

#include <emscripten/val.h>
#include <sstream>
#include <vector>

int main() {
    const auto port = emscripten::val::global("location")["port"].as<std::string>();
    if (setenv("WEBCPP_BEAST_FIXTURE_HOST", "127.0.0.1", 1) != 0) {
        return 1;
    }
    if (setenv("WEBCPP_BEAST_FIXTURE_PORT", port.c_str(), 1) != 0) {
        return 1;
    }
    for (const auto* method : {"get", "head", "post", "put", "patch", "delete"}) {
        std::vector<std::string> storage{"http-client-methods", method};
        std::vector<char*> arguments;
        arguments.reserve(storage.size());
        for (auto& value : storage) {
            arguments.push_back(value.data());
        }
        // This mutable object is passed through the upstream asynchronous or stream interface.
        // NOLINTNEXTLINE(misc-const-correctness)
        std::ostringstream output;
        auto* original = std::cout.rdbuf(output.rdbuf());
        const auto result = application_main(static_cast<int>(arguments.size()), arguments.data());
        std::cout.rdbuf(original);
        std::cout << output.str();
        if (result != 0 || output.str().find("200 OK") == std::string::npos) {
            return 1;
        }
    }
    std::cout << "application http-client-methods: passed\n";
    return 0;
}
